import{_ as e,o as t,c as a,a3 as n}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Android companion app","description":"The ShipperDog Android companion app - an optional preview installer for testers on Android.","frontmatter":{"description":"The ShipperDog Android companion app - an optional preview installer for testers on Android."},"headers":[],"relativePath":"how-to/automation/companion-app.md","filePath":"how-to/automation/companion-app.md"}'),i={name:"how-to/automation/companion-app.md"};function r(s,o,p,d,l,h){return t(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="android-companion-app" tabindex="-1">Android companion app <a class="header-anchor" href="#android-companion-app" aria-label="Permalink to &quot;Android companion app&quot;">​</a></h1><p>The companion app is an optional Android installer for ShipperDog testing. It is a <strong>preview</strong> — a working prototype, not broadly available: unless your team explicitly hands you the app and asks you to use it, you do not need it. The <a href="/shipperdog/snapshot/how-to/portal/browse-apps">Tester Portal</a> in your phone&#39;s browser is the standard way to install builds, and everything in the portal guides works without the companion.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>For a tester whose team provides it:</p><ul><li><strong>Sign in once</strong> with your regular portal email and password.</li><li><strong>See your apps</strong> — the same authorized builds the portal shows, refreshed live every time you open it.</li><li><strong>Install in one tap</strong> — tap Install on a build and the app handles the download; Android still shows its own install confirmation (every install on Android asks, by design).</li><li><strong>Spot updates</strong> — the list marks which builds are installed and which have an update available.</li><li><strong>Report issues</strong> — the Report action opens the portal&#39;s <a href="/shipperdog/snapshot/how-to/portal/feedback">feedback form</a> for that build.</li></ul><p>Android only — Apple&#39;s rules give iOS installs a single road (TestFlight), so there is no iOS companion.</p><h2 id="why-preview" tabindex="-1">Why &quot;preview&quot; <a class="header-anchor" href="#why-preview" aria-label="Permalink to &quot;Why &quot;preview&quot;&quot;">​</a></h2><p>The companion started as a time-boxed prototype to answer one question: is a dedicated installer worth building, or does the browser portal serve testers well enough? The prototype works end to end, but the team decided not to polish and announce it until real usage shows testers need it. The decision and the conditions that would flip it are on record in the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/companion-spike.md" target="_blank" rel="noreferrer">companion spike decision memo</a>.</p><p><strong>See also:</strong> the portal way — <a href="/shipperdog/snapshot/how-to/portal/install-android">install on Android</a>.</p>',9)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
